   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Yep. There were plenty more videos like that—recorded every year. Plenty of impromptu performances too, like barging in during the Prime Minister's meetings with foreign dignitaries to deliver scripted speeches about how grateful I was to Liboselle.", msg_color="", msg_size=0, talker="Argo", audio="", img="arts/ui/bg/story/storybg_ACT201_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4517", 0, 0, -9.5, 200}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="What else could I do? I was raised by Liboselle. Of course I should be wholeheartedly grateful to the country that took me in.", msg_color="", msg_size=0, talker="Argo", audio="", img="arts/ui/bg/story/storybg_ACT201_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4517", 0, 0, -9.5, 200}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
